source /tmp/dep/vars.sh; TOK=$(python3 /tmp/aztok.py)
for L in eastus2 westus2 westus3 centralus westeurope northeurope uksouth francecentral germanywestcentral swedencentral canadacentral australiaeast japaneast eastasia southeastasia; do
  R=$(curl -sS -H "Authorization: Bearer $TOK" "https://management.azure.com/subscriptions/$SUB/providers/Microsoft.DBforPostgreSQL/locations/$L/capabilities?api-version=2024-08-01")
  echo "$L => $(echo "$R" | python3 -c "
import json,sys
try:
  d=json.load(sys.stdin)
except Exception as e:
  print('ERR'); raise SystemExit
v=d.get('value',[])
ok=[z for z in v if z.get('status')=='Available']
if not v: print('no-data', d.get('error',{}).get('code',''))
else:
  z=v[0]
  vers=set()
  for zz in v:
    for e in zz.get('supportedFlexibleServerEditions',[]):
      if e.get('name')=='Burstable' and e.get('status')=='Available':
        for sv in e.get('supportedServerVersions',[]):
          if sv.get('status')=='Available': vers.add(sv.get('name'))
  print(z.get('status'), '| burstable vers:', sorted(vers), '|', (z.get('reason') or '')[:60])
")"
done

